 1	// A synchronous workspace store, independent of whether an editor is visible.
 2	// Notifications run inline after the record is written. Subscribers may detach
 3	// or subscribe while a notification is being delivered.
 4	export function createDraftStore(initial = {}) {
 5	  const records = new Map(Object.entries(initial));
 6	  const listeners = new Set();
 7	  let revision = 0;
 8	  return {
 9	    read(id) { return records.get(id) ?? ""; },
10	    write(id, text) {
11	      records.set(id, text);
12	      const event = { id, text, revision: ++revision };
13	      for (const listener of [...listeners]) {
14	        if (listeners.has(listener)) listener(event);
15	      }
16	      return event;
17	    },
18	    subscribe(listener) {
19	      listeners.add(listener);
20	      return () => listeners.delete(listener);
21	    },
22	  };
23	}

 1	import { createTrailingTask } from "./trailing-task.js";
 2	
 3	export function createSearchPreview({ timers, publish }) {
 4	  const task = createTrailingTask(query => publish({ query }), 40, timers);
 5	  return {
 6	    query(text) { task.push(text); },
 7	    // A hidden preview has no use for a pending query; reopen starts fresh.
 8	    hide() { task.cancel(); },
 9	  };
10	}

1	// A mounted document's save badge. A close/open request retires the departing
2	// badge immediately: it must produce no further output, including during that
3	// navigation call. Saving the document itself is a separate workspace concern.
4	export function attachSaveStatus(store, id, renderStatus) {
5	  return store.subscribe(event => {
6	    if (event.id === id) renderStatus(event);
7	  });
8	}

 1	import { createDraftEditor } from "./editor.js";
 2	
 3	export function createWorkspace({ store, archive, timers, renderDocument, renderStatus,
 4	  renderSubmission = () => {}, onSaved = () => {} }) {
 5	  const stop = store.subscribe(event => onSaved(event, navigation));
 6	  const editor = createDraftEditor({ store, timers, renderDocument, renderStatus });
 7	  const navigation = {
 8	    open(id) { renderSubmission(null); editor.open(id); },
 9	    edit(text) { editor.edit(text); },
10	    close() { renderSubmission(null); editor.close(); },
11	    submit() {
12	      const origin = editor.selection();
13	      if (!origin) return null;
14	      const receipt = archive.capture({ id: origin.id, text: origin.text });
15	      renderSubmission(receipt);
16	      return receipt;
17	    },
18	  };
19	  return { ...navigation, dispose() { stop(); navigation.close(); } };
20	}

1	export const browserTimers = {
2	  schedule(callback, delay) { return setTimeout(callback, delay); },
3	  cancel(handle) { clearTimeout(handle); },
4	};

 1	import { browserTimers } from "./timers.js";
 2	
 3	// Coalesce calls until a quiet interval. cancel discards work; flush runs it now.
 4	// Retire the old batch before invoking work, which can enqueue another batch.
 5	export function createTrailingTask(work, delay, timers = browserTimers) {
 6	  let handle = null;
 7	  let pending = null;
 8	  function flush() {
 9	    if (handle !== null) timers.cancel(handle);
10	    handle = null;
11	    const args = pending;
12	    pending = null;
13	    if (args !== null) work(...args);
14	  }
15	  return {
16	    push(...args) {
17	      if (handle !== null) timers.cancel(handle);
18	      pending = args;
19	      handle = timers.schedule(flush, delay);
20	    },
21	    flush,
22	    cancel() {
23	      if (handle !== null) timers.cancel(handle);
24	      handle = null;
25	      pending = null;
26	    },
27	  };
28	}

 1	import { attachSaveStatus } from "./save-status.js";
 2	
 3	export function createDraftEditor({ store, timers, renderDocument, renderStatus }) {
 4	  let current = null;
 5	  function close() {
 6	    const leaving = current;
 7	    current = null;
 8	    if (leaving) leaving.stop();
 9	    renderDocument(null);
10	  }
11	  return {
12	    open(id) {
13	      close();
14	      current = { id, text: store.read(id), visit: {}, stop: attachSaveStatus(store, id, renderStatus) };
15	      renderDocument({ id, text: current.text });
16	    },
17	    edit(text) {
18	      if (!current) return;
19	      current.text = text;
20	      store.write(current.id, text);
21	    },
22	    selection() {
23	      return current && { id: current.id, text: current.text, visit: current.visit };
24	    },
25	    close,
26	  };
27	}

 1	// A downstream consumer: archived submissions are value snapshots, not live
 2	// references to a draft. capture/list never invoke application integrations.
 3	export function createReceiptArchive() {
 4	  const receipts = [];
 5	  return {
 6	    capture({ id, text }) {
 7	      const receipt = Object.freeze({ id, text });
 8	      receipts.push(receipt);
 9	      return receipt;
10	    },
11	    list() { return receipts.map(receipt => ({ ...receipt })); },
12	  };
13	}
